static void torture_asn1_put_tag_short(void **state)
{
        unsigned int tag = 0xAC;
        const u8 expected[] = {0xAC, 0x01, 0x02};
        const u8 data[] = {0x02};
        size_t data_len = 1;
        u8 out[10];
        size_t out_len = sizeof(out);
        u8 *p = out;
        int rv;

        /* Without the out and out_len we are getting expected length */
        rv = sc_asn1_put_tag(tag, data, data_len, NULL, 0, &p);
        assert_int_equal(rv, sizeof(expected));
        assert_ptr_equal(p, out);
        assert_int_equal(rv, SC_ERROR_BUFFER_TOO_SMALL);
}

static void torture_asn1_put_tag_without_data(void **state)
{
        unsigned int tag = 0xAC;
        const u8 expected[] = {0xAC, 0x01};
        size_t data_len = 1;
        u8 out[10];
        size_t out_len = sizeof(out);
        u8 *p = out;
        int rv;

        /* Without the out and out_len we are getting expected length */
        rv = sc_asn1_put_tag(tag, NULL, data_len, NULL, 0, &p);
        assert_int_equal(rv, sizeof(expected) + data_len);
        assert_ptr_equal(p, out);

        /* Now we do the actual encoding, but data field is not filled */
        rv = sc_asn1_put_tag(tag, NULL, data_len, out, out_len, &p);
        assert_int_equal(rv, SC_SUCCESS);
        assert_memory_equal(out, expected, sizeof(expected));
        assert_ptr_equal(p, out + sizeof(expected));
}

static void torture_asn1_encode_simple(void **state)
{
        sc_context_t *ctx = *state;
        struct sc_asn1_entry asn1[] = {
                { "OctetString", SC_ASN1_OCTET_STRING, 0x05, SC_ASN1_PRESENT, NULL, NULL },
                { NULL , 0 , 0 , 0 , NULL , NULL }
        };
        u8 expected[] = {0x05, 0x09, 't', 'e', 's', 't', ' ', 'd', 'a', 't', 'a'};
        char *data = "test data";
        size_t datalen = strlen(data);
        u8 *outptr = NULL;
        size_t outlen = 0;
        int rv;

        /* NULL arguments should not crash */
        rv = sc_asn1_encode(NULL, NULL, NULL, NULL);
        assert_int_equal(rv, SC_ERROR_INVALID_ARGUMENTS);

        /* NULL asn1 entry should not crash */
        rv = sc_asn1_encode(ctx, NULL, NULL, NULL);
        assert_int_equal(rv, SC_ERROR_INVALID_ARGUMENTS);

        /* Real example of encoding an octet string */
        asn1[0].parm = data;
        asn1[0].arg = &datalen;
        rv = sc_asn1_encode(ctx, asn1, &outptr, &outlen);
        assert_int_equal(rv, SC_SUCCESS);
        assert_int_equal(outlen, sizeof(expected));
        assert_memory_equal(expected, outptr, sizeof(expected));
        free(outptr);

        /* Context is not needed */
        rv = sc_asn1_encode(NULL, asn1, &outptr, &outlen);
        assert_int_equal(rv, SC_SUCCESS);
        free(outptr);
}

